package net.officefloor.hq.app.holiday;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's list of holidays. A claim's due-by, when fixed at its creation, counts business days that skip the
 * weekends and the holidays on the sheet then. A holiday added later re-fixes the due-by of every claim that is not
 * SETTLED or VOID and is due on or after it, from the claim's date with the terms it was fixed with.
 */
@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final SheetService sheets;
    private final ClaimRepository claims;
    private final RollupService rollup;
    private final Audit audit;

    public HolidayService(HolidayRepository holidays, SheetService sheets, ClaimRepository claims,
            RollupService rollup, Audit audit) {
        this.holidays = holidays;
        this.sheets = sheets;
        this.claims = claims;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's holidays, earliest first. */
    @Transactional(readOnly = true)
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId);
    }

    /**
     * Adds a holiday to the sheet, re-fixing the due-by of each claim not SETTLED or VOID that is due on or after it
     * over the holidays now on the sheet; a figure that moves is recorded as for any change. Refused when the date is
     * already on the list.
     */
    @Transactional
    public Holiday add(String by, String sheetId, LocalDate date) {
        sheets.lock(sheetId);
        if (holidays.existsBySheetIdAndDate(sheetId, date)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, date + " is already a holiday.");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Holiday added = holidays.saveAndFlush(new Holiday(sheetId, date));
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + by + " date=" + date);
        Set<LocalDate> days = holidayDates(sheetId);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                    || claim.getDueBy() == null || claim.getDueBy().isBefore(date)) {
                continue;
            }
            claim.setDueBy(businessDaysAfter(claim.getDate(), claim.getTerms(), days));
        }
        claims.flush();
        rollup.recordChanges(by, sheetId, before);
        return added;
    }

    /**
     * The terms-th business day after the date: counting forward from the day after it, skipping every Saturday,
     * Sunday and holiday on the sheet. Terms of 0 is the date itself.
     */
    @Transactional(readOnly = true)
    public LocalDate dueBy(String sheetId, LocalDate date, int terms) {
        return businessDaysAfter(date, terms, holidayDates(sheetId));
    }

    private Set<LocalDate> holidayDates(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(Holiday::getDate)
                .collect(Collectors.toSet());
    }

    /** The terms-th day after the date that is neither a Saturday, a Sunday nor one of the holidays. */
    public static LocalDate businessDaysAfter(LocalDate date, int terms, Set<LocalDate> holidays) {
        LocalDate day = date;
        for (int counted = 0; counted < terms;) {
            day = day.plusDays(1);
            if (day.getDayOfWeek() != DayOfWeek.SATURDAY && day.getDayOfWeek() != DayOfWeek.SUNDAY
                    && !holidays.contains(day)) {
                counted++;
            }
        }
        return day;
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, signal, untracked } from '@angular/core';
import { FigPipe } from '../../core/locale';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

interface HolidayView {
  id: number;
  date: string;
}

// The active sheet's holidays: a claim's due-by, fixed when the claim is created, counts business days that skip
// weekends and the holidays on the sheet then. A date already on the list is refused.
@Component({
  selector: 'app-holidays',
  imports: [FigPipe],
  template: `
    <section aria-label="Holidays">
      <h2>Holidays</h2>
      <form (submit)="add($event)" aria-label="Add a holiday">
        <label for="holiday-date">Holiday</label>
        <input
          id="holiday-date"
          type="date"
          data-testid="holiday-date"
          [value]="date()"
          (input)="date.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="holiday-add">Add holiday</button>
        @if (error(); as err) {
          <p role="alert" data-testid="holiday-error">{{ err | fig }}</p>
        }
      </form>

      <ul aria-label="Holidays on the sheet">
        @for (h of holidays(); track h.id) {
          <li [attr.data-testid]="'holiday-row-' + h.date">{{ h.date | fig }}</li>
        }
      </ul>
    </section>
  `,
})
export class Holidays {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly holidays = signal<readonly HolidayView[]>([]);
  protected readonly date = signal('');
  protected readonly error = signal<string | null>(null);
  // A submit in flight: a second one before it answers is ignored.
  private submitting = false;

  constructor() {
    // Re-read the holidays from the store each time a sheet is loaded.
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.error.set(null);
        this.holidays.set([]);
        if (id) this.load(id).catch(() => this.error.set('Could not load the holidays.'));
      });
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  private async load(sheet: string): Promise<void> {
    const l = await firstValueFrom(
      this.http.get<HolidayView[]>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`),
    );
    if (this.session.sheetId() === sheet) this.holidays.set(l);
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const date = this.date().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.error.set('Enter a date as yyyy-mm-dd.');
      return;
    }
    if (this.holidays().some((h) => h.date === date)) {
      this.error.set(`${date} is already a holiday.`);
      return;
    }
    this.submitting = true;
    try {
      const h = await firstValueFrom(
        this.http.post<HolidayView>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`, { date }),
      );
      if (this.session.sheetId() === sheet) {
        this.holidays.update((l) => [...l, h].sort((a, b) => a.date.localeCompare(b.date)));
      }
    } catch (err) {
      this.error.set(
        err instanceof HttpErrorResponse && err.status === 409
          ? `${date} is already a holiday.`
          : 'Could not add the holiday.',
      );
    } finally {
      this.submitting = false;
    }
  }
}
